import path from 'node:path';
const fileMenu = path.join(import.meta.dirname, 'data', 'menu.json');
console.log('Data:', fileMenu);

import path from 'node:path';
const fileMenu = path.join(import.meta.dirname, 'data', 'menu.json');
console.log('Data:', fileMenu);
const muat = () => new Promise((r) => setTimeout(() => r(['Kopi Susu', 'Teh Tarik']), 20));
const menu = await muat();
console.log('Menu:', menu.length);

// === promo.js ===
export default function (harga) {
  return harga * 0.8;
}
// === main.js ===
import path from 'node:path';
const fileMenu = path.join(import.meta.dirname, 'data', 'menu.json');
console.log('Data:', fileMenu);
const muat = () => new Promise((r) => setTimeout(() => r(['Kopi Susu', 'Teh Tarik']), 20));
const menu = await muat();
console.log('Menu:', menu.length);
const adaPromo = true;
if (adaPromo) {
  const { default: promo } = await import('./promo.js');
  console.log('Harga promo:', promo(18000));
}

